def pack(lang):
    lang = (lang or "tr").lower()
    if lang == "tr" or lang not in ORDER:
        return {"lang": "tr", "names": LANG_TR, "phrases": {},
                "prefixes": {}, "words": {}}
    i = ORDER.index(lang)
    return {
        "lang": lang,
        "names": LANG_TR,
        "phrases": {k: v[i] for k, v in P.items()},
        "prefixes": {k: v[i] for k, v in PRE.items()},
        "words": {k: v[i] for k, v in WORD.items()},
    }
